const input = ($input.first() && $input.first().json) || {};
const source = input.source || "UNKNOWN";
const rawText = (input.rawText || "").trim();
const receivedAt = input.receivedAt || new Date().toISOString();
const chatId = input.chatId || null;
const senderHint = input.senderHint || null;

// Pre-structured input (e.g. Manual Import with explicit fields) skips heuristic parsing.
if (input.amount && input.description) {
  return [{
    json: {
      source, rawText, receivedAt, chatId, senderHint,
      amount: String(input.amount),
      currency: input.currency || "AED",
      description: String(input.description).slice(0, 100),
      date: input.date ? new Date(input.date).toISOString() : receivedAt,
      type: input.type || "EXPENSE",
      paymentMethod: input.paymentMethod || "Bank Transfer",
      confidence: 1,
      parseOk: true,
      parseNotes: ["pre-structured input, heuristic parsing skipped"],
    },
  }];
}

const notes = [];
let confidence = 0;

// Amount: "AED 45.50", "$12.00", "45.50 AED", "PHP1,250.00"
const amountMatch = rawText.match(/(AED|USD|PHP|SAR|EUR|GBP|\$|₱)?\s?([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?)\s?(AED|USD|PHP|SAR|EUR|GBP)?/i);
let amount = null;
let currency = null;
if (amountMatch) {
  amount = amountMatch[2].replace(/,/g, "");
  const rawCurrency = (amountMatch[1] || amountMatch[3] || "AED").toUpperCase();
  currency = rawCurrency === "$" ? "USD" : rawCurrency === "₱" ? "PHP" : rawCurrency;
  confidence += 0.4;
} else {
  notes.push("no amount found");
}

// Date: yyyy-mm-dd, dd/mm/yyyy, dd-mm-yyyy
const dateMatch = rawText.match(/(\d{4}-\d{2}-\d{2})|(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/);
let date = receivedAt;
if (dateMatch) {
  const parsed = new Date(dateMatch[0]);
  if (!isNaN(parsed.getTime())) {
    date = parsed.toISOString();
    confidence += 0.2;
  } else {
    notes.push("date pattern found but unparseable, using receivedAt");
  }
} else {
  notes.push("no date found, using receivedAt");
}

// Type guess
const isIncome = /\b(credit|received|refund|salary|deposit|payroll)\b/i.test(rawText);
const type = isIncome ? "INCOME" : "EXPENSE";

// Description: strip the matched amount/date substrings, collapse whitespace
let description = rawText;
if (amountMatch) description = description.replace(amountMatch[0], " ");
if (dateMatch) description = description.replace(dateMatch[0], " ");
description = description.replace(/\s+/g, " ").trim();
if (description.length > 0) {
  confidence += 0.2;
} else {
  description = `Imported transaction (${source})`;
  notes.push("no description text remained after stripping amount/date");
}
description = description.slice(0, 100);

if (currency) confidence += 0.2;

const parseOk = amount !== null;
if (!parseOk) notes.push("parseOk=false: amount is required to proceed");

return [{
  json: {
    source, rawText, receivedAt, chatId, senderHint,
    amount, currency: currency || "AED", description, date, type,
    paymentMethod: input.paymentMethod || "Bank Transfer",
    confidence: Math.round(confidence * 100) / 100,
    parseOk,
    parseNotes: notes,
  },
}];
